<?php
namespace app\service;use think\facade\Db;
class RateLimiter{
 private static ?array $settings=null;
 private static function settings():array{if(self::$settings!==null)return self::$settings;$r=RedisService::connect();$rk='lumen:cfg:ratelimit';if($r)try{$v=$r->get($rk);if($v){$x=json_decode($v,true);if(is_array($x))return self::$settings=$x;}}catch(\Throwable $e){}$rows=Db::name('settings')->where('key','like','ratelimit.%')->field('key,value')->select()->toArray();$s=[];foreach($rows as $x)$s[$x['key']]=$x['value'];if($r)try{$r->setex($rk,300,json_encode($s));}catch(\Throwable $e){}return self::$settings=$s;}
 public static function check(array $key,string $ip):array{$s=self::settings();if(($s['ratelimit.enabled']??'0')!=='1')return[true,null];$r=RedisService::connect();if(!$r)return[true,'degraded'];$bucket=date('YmdHi');$checks=[['ip:'.$ip,(int)($s['ratelimit.ip_rpm']??300)]];if(!empty($key['id']))$checks[]=['key:'.$key['id'],(int)($s['ratelimit.key_rpm']??120)];if(!empty($key['user_id']))$checks[]=['user:'.$key['user_id'],(int)($s['ratelimit.user_rpm']??300)];$keys=[];$limits=[];$names=[];foreach($checks as [$name,$limit]){if($limit<1)continue;$keys[]='lumen:rl:'.$bucket.':'.$name;$limits[]=$limit;$names[]=$name;}if(!$keys)return[true,null];$script="for i=1,#KEYS do local n=redis.call('INCR',KEYS[i]);if n==1 then redis.call('EXPIRE',KEYS[i],90) end;if n>tonumber(ARGV[i]) then return i end end;return 0";$result=$r->eval($script,array_merge($keys,$limits),count($keys));$failed=(int)$result;return $failed>0&&isset($names[$failed-1])?[false,$names[$failed-1]]:[true,null];}
}
